bool Game::playerSaySpell(const std::shared_ptr<Player> &player, SpeakClasses type, const std::string &text, const Position* optionalTarget) {
	if (player->walkExhausted()) {
		return true;
	}

	std::string words = text;
	TalkActionResult_t result = g_talkActions().checkPlayerCanSayTalkAction(player, type, words);
	if (result == TALKACTION_BREAK) {
		return true;
	}

bool Player::walkExhausted() const {
	if (hasCondition(CONDITION_PARALYZE)) {
		return lastWalking > OTSYS_TIME();
	}

	return false;
}

void Player::setWalkExhaust(int64_t value) {
	lastWalking = OTSYS_TIME() + value;
}

void Player::updateParalyzeWalkExhaust() {
	if (!hasCondition(CONDITION_PARALYZE)) {
		return;
	}

	const int32_t walkDelay = getWalkDelay();
	if (walkDelay > 0) {
		setWalkExhaust(walkDelay);
	}
}

